func TestIsLoopbackAddr(t *testing.T) {
	cases := []struct {
		addr string
		want bool
	}{
		{"127.0.0.1:7777", true},
		{"localhost:7777", true},
		{"LOCALHOST:7777", true},
		{"[::1]:7777", true},
		{":7777", false},   // wildcard: binds every interface, including non-loopback
		{"0.0.0.0:7777", false},
		{"[::]:7777", false},
		{"192.168.1.5:7777", false},
		{"example.com:7777", false}, // unresolved hostname: fail closed
		{"", false},
	}
	for _, tc := range cases {
		if got := isLoopbackAddr(tc.addr); got != tc.want {
			t.Errorf("isLoopbackAddr(%q) = %v, want %v", tc.addr, got, tc.want)
		}
	}
}

// TestRequireBearerToken_NoTokenLeavesHandlerOpen pins the default behavior
// this PR must not regress: an operator who never sets --auth-token or
// QUICKCOMMERCE_MCP_TOKEN and binds loopback keeps working exactly as
// before, unauthenticated.
func TestRequireBearerToken_NoTokenLeavesHandlerOpen(t *testing.T) {
	called := false
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { called = true })

	handler := requireBearerToken("", next)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/mcp", nil))

	if !called {
		t.Fatal("expected next handler to run when no token is configured")
	}
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusOK)
	}
}

// TestRequireBearerToken_RejectsMissingOrWrongToken is the core of this
// PR's fix: once a token is configured, requests without a matching Bearer
// header must never reach the wrapped MCP handler -- that handler is what
// exposes credentialed API, SQLite, and CLI shell-out tools.
func TestRequireBearerToken_RejectsMissingOrWrongToken(t *testing.T) {
	called := false
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { called = true })
	handler := requireBearerToken("secret-token", next)

	cases := []struct {
		name   string
		header string
	}{
		{"missing header", ""},
		{"wrong token", "Bearer wrong-token"},
		{"no Bearer prefix", "secret-token"},
		{"empty bearer value", "Bearer "},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			called = false
			req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
			if tc.header != "" {
				req.Header.Set("Authorization", tc.header)
			}
			rec := httptest.NewRecorder()
			handler.ServeHTTP(rec, req)

			if called {
				t.Fatal("wrapped handler ran despite missing/invalid bearer token")
			}
			if rec.Code != http.StatusUnauthorized {
				t.Fatalf("status = %d, want %d", rec.Code, http.StatusUnauthorized)
			}
		})
	}
}

